import sys
from pathlib import Path
MAX_BYTES = 1000000


def resolve_inside(root: str, relative: str) -> Path:
    """Requirements:
Resolve symlinks and .. first, then require the target to sit strictly inside the resolved root (compare path parts, not string prefixes)."""
    if not relative.strip():
        raise ValueError('refused: the path is empty')
    base = Path(root).resolve()
    target = (base / relative).resolve()
    if base not in target.parents:
        raise ValueError(f'refused: {relative} is not inside {root}')
    return target


def safe_write_text(root: str, relative: str, text: str, max_bytes: int) -> None:
    """Requirements:
Every check happens before anything is written."""
    data = text.encode('utf-8')
    if len(data) > max_bytes:
        raise ValueError(f'refused: {len(data)} bytes is over the {max_bytes}-byte limit')
